from math import gcd
from typing import List

def decryptCodeLock(codeSequence: List[int], maxValue: int) -> int:
    n = len(codeSequence)
    present = set(codeSequence)
    best = None
    # 选 maxValue 至少能得到 maxValue - n，比它更小的 v 不可能更优
    for v in range(max(1, maxValue - n), maxValue + 1):
        bad = sum(1 for x in codeSequence if gcd(x, v) != 1)
        if v in present:
            cost = bad - 1 if v != 1 else 0   # 选中那个本来就是 v 的位置，不用改它
        else:
            cost = max(bad, 1)                # 把某个"坏"位置改成 v；没有坏位置也得改一个
        if best is None or v - cost > best:
            best = v - cost
    return best
